#include "bitcoin/address/format.hpp"
#include <nlohmann/json.hpp>
#include <fstream>
#include <iostream>
int main(int argc,char* argv[]){ if(argc!=7||std::string_view(argv[1])!="--input"||std::string_view(argv[3])!="--json-report"||std::string_view(argv[5])!="--csv"){std::cerr<<"Usage: address_format_report --input <file> --json-report <file> --csv <file>\n";return 2;} std::ifstream in(argv[2]); if(!in){std::cerr<<"could not open input\n";return 1;} nlohmann::json rows=nlohmann::json::array(); std::ofstream csv(argv[6]); csv<<"line_number,original,normalized,type,valid,error\n";std::string line;size_t n=0;while(std::getline(in,line)){++n;auto x=crypto_research::bitcoin::address::inspect_public_address(line);if(x.normalized.empty())continue;rows.push_back({{"line_number",n},{"original",line},{"normalized",x.normalized},{"type",crypto_research::bitcoin::address::to_string(x.type)},{"valid",x.valid},{"error",x.error}});csv<<n<<",\""<<line<<"\",\""<<x.normalized<<"\","<<crypto_research::bitcoin::address::to_string(x.type)<<","<<x.valid<<",\""<<x.error<<"\"\n";}std::ofstream out(argv[4]);out<<nlohmann::json{{"tool","address_format_report"},{"rows",rows}}.dump(2)<<'\n';}
